import{_ as t,o,c as a,ag as d}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"LuaStarterMod — 模组 Lua 起步模板","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/examples/LuaStarterMod/README.md","filePath":"Modders/examples/LuaStarterMod/README.md"}'),n={name:"Modders/examples/LuaStarterMod/README.md"};function r(i,e,s,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="luastartermod-—-模组-lua-起步模板" tabindex="-1">LuaStarterMod — 模组 Lua 起步模板 <a class="header-anchor" href="#luastartermod-—-模组-lua-起步模板" aria-label="Permalink to &quot;LuaStarterMod — 模组 Lua 起步模板&quot;">​</a></h1><p>一个完整可用的 Lua 模组模板：复制目录、改名字、就能跑。包含每回合触发的入口函数、参数传递示例、API 冒烟自检函数。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LuaStarterMod/</span></span>
<span class="line"><span>├── ModOptions.json          ← 模组元信息（名称/作者/版本）</span></span>
<span class="line"><span>├── jsons/</span></span>
<span class="line"><span>│   └── GlobalUniques.json   ← 用 TriggerLuaFunction 声明触发时机</span></span>
<span class="line"><span>└── scripts/</span></span>
<span class="line"><span>    ├── main.lua             ← onTurnStart / onTurnEnd 入口函数</span></span>
<span class="line"><span>    └── api_test.lua         ← selfCheck 冒烟测试（可选）</span></span></code></pre></div><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>把 <code>LuaStarterMod</code> 目录复制到游戏的 <code>mods/</code> 文件夹（桌面版位于游戏根目录，Android 在 <code>Android/data/com.unciv.app/files/mods/</code>），改成你自己的模组名</li><li>编辑 <code>ModOptions.json</code>：改 <code>name</code>、<code>author</code>；<code>modVersion</code> 用 <code>n.n.n</code> 格式</li><li>编辑 <code>jsons/GlobalUniques.json</code>：把 <code>LuaStarterMod</code> 前缀全部换成你的模组名</li><li>新建游戏 → 勾选你的模组 → 开始游戏</li><li>每回合开始会收到 &quot;+1 Gold&quot; 通知——模组已生效</li></ol><h2 id="测试你的脚本" tabindex="-1">测试你的脚本 <a class="header-anchor" href="#测试你的脚本" aria-label="Permalink to &quot;测试你的脚本&quot;">​</a></h2><ul><li><strong>冒烟测试</strong>：取消 <code>GlobalUniques.json</code> 中 <code>selfCheck</code> 触发行的注释（<code>&lt;before turn number [1]&gt;</code> 表示第 1 回合前触发），开局第一回合后查看日志（开发者控制台或日志文件）中的 <code>test API:</code> 输出</li><li><strong>mod-ci 检查</strong>：在模组目录运行 <code>java -jar Unciv.jar mod-ci</code>（或 <code>Unciv mod-ci</code>），自动检查 JSON 校验 + Lua 语法 + 函数引用 + API 拼写</li><li><strong>编辑器补全</strong>：参见 Lua-Modding.md 的「编辑器设置」——把 <code>lua-api.lua</code> 类型定义配进 LuaLS 后，写 <code>ctx.</code> 就有自动补全</li></ul><h2 id="触发时机速查-globaluniques-json" tabindex="-1">触发时机速查（GlobalUniques.json） <a class="header-anchor" href="#触发时机速查-globaluniques-json" aria-label="Permalink to &quot;触发时机速查（GlobalUniques.json）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>触发条件</th><th>示例</th></tr></thead><tbody><tr><td>每回合开始/结束</td><td><code>&lt;upon turn start&gt;</code> / <code>&lt;upon turn end&gt;</code></td></tr><tr><td>研究某科技</td><td><code>&lt;upon discovering [Writing] technology&gt;</code></td></tr><tr><td>建城/攻城</td><td><code>&lt;upon founding a city&gt;</code> / <code>&lt;upon conquering a city&gt;</code></td></tr><tr><td>第 N 回合前</td><td><code>&lt;before turn number [10]&gt;</code></td></tr></tbody></table><p>完整语法见文档 Lua-Modding.md。</p><hr><h1 id="luastartermod-—-lua-mod-starter-template" tabindex="-1">LuaStarterMod — Lua mod starter template <a class="header-anchor" href="#luastartermod-—-lua-mod-starter-template" aria-label="Permalink to &quot;LuaStarterMod — Lua mod starter template&quot;">​</a></h1><p>A complete, working Lua mod template: copy the folder, rename it, and it runs. Includes per-turn entry functions, a parameter-passing example and an API smoke-test function.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><ol><li>Copy the <code>LuaStarterMod</code> folder into the game&#39;s <code>mods/</code> folder, rename it to your mod</li><li>Edit <code>ModOptions.json</code>: set <code>name</code> / <code>author</code>; <code>modVersion</code> uses <code>n.n.n</code></li><li>Edit <code>jsons/GlobalUniques.json</code>: replace every <code>LuaStarterMod</code> prefix with your mod name</li><li>New game → enable your mod → start</li><li>You&#39;ll get a &quot;+1 Gold&quot; notification every turn start — the mod is live</li></ol><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li><strong>Smoke test</strong>: uncomment the <code>selfCheck</code> trigger in <code>GlobalUniques.json</code> (<code>&lt;before turn number [1]&gt;</code> fires before turn 1); check the <code>test API:</code> lines in the log</li><li><strong>mod-ci</strong>: run <code>java -jar Unciv.jar mod-ci</code> (or <code>Unciv mod-ci</code>) in the mod folder — checks JSON validation + Lua syntax + function references + API spelling</li><li><strong>Editor support</strong>: see &quot;Editor setup&quot; in Lua-Modding.md — point LuaLS at <code>lua-api.lua</code> for autocompletion</li></ul><h2 id="trigger-quick-reference-globaluniques-json" tabindex="-1">Trigger quick reference (GlobalUniques.json) <a class="header-anchor" href="#trigger-quick-reference-globaluniques-json" aria-label="Permalink to &quot;Trigger quick reference (GlobalUniques.json)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Example</th></tr></thead><tbody><tr><td>Turn start / end</td><td><code>&lt;upon turn start&gt;</code> / <code>&lt;upon turn end&gt;</code></td></tr><tr><td>Tech discovered</td><td><code>&lt;upon discovering [Writing] technology&gt;</code></td></tr><tr><td>City founded / conquered</td><td><code>&lt;upon founding a city&gt;</code> / <code>&lt;upon conquering a city&gt;</code></td></tr><tr><td>Before turn N</td><td><code>&lt;before turn number [10]&gt;</code></td></tr></tbody></table><p>Full syntax: see Lua-Modding.md.</p>`,21)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
